export function structureRanges(data){return {tunnels:data.structures.filter(x=>x.kind==='tunnel'),bridges:data.structures.filter(x=>x.kind==='bridge'),groundGaps:data.structures.filter(x=>(x.kind==='bridge'&&(!x.sourceType||x.sEnd-x.sStart>=20))||x.kind==='river')};}
export function segmentIntersects(start,end,range,padding=0){return end>range.sStart-padding&&start<range.sEnd+padding;}
export function corridorOccupied(data,s,offset){return data.structures.some(x=>{if(!segmentIntersects(s-.1,s+.1,x,6))return false;if((x.kind==='bridge'&&(!x.sourceType||x.sEnd-x.sStart>=20))||x.kind==='river')return true;if(x.kind==='tunnel')return Math.abs(offset)<10;if(x.kind==='cutting'||x.kind==='cutting-wall'||x.kind==='retaining-wall')return Math.abs(offset)<13;return Math.abs(offset)<15;});}
